import{_ as a,o as e,c as o,a2 as i}from"./chunks/framework.BjkiRu3Q.js";const q=JSON.parse('{"title":"AI 编程与验收","description":"","frontmatter":{"title":"AI 编程与验收"},"headers":[],"relativePath":"md/ai-code/index.md","filePath":"md/ai-code/index.md","lastUpdated":1795434315000}'),r={name:"md/ai-code/index.md"};function l(n,t,d,s,u,c){return e(),o("div",null,[...t[0]||(t[0]=[i('<h1 id="ai-编程与验收" tabindex="-1">AI 编程与验收 <a class="header-anchor" href="#ai-编程与验收" aria-label="Permalink to &quot;AI 编程与验收&quot;">​</a></h1><p>用 AI 写生产代码，难点已经从&quot;能不能写出来&quot;变成了&quot;怎么确认它写对了&quot;。这个板块记录我自己踩过的坑：需求要怎么写才不留歧义，交付物要怎么验证才不算自欺。</p><h2 id="这个板块写什么" tabindex="-1">这个板块写什么 <a class="header-anchor" href="#这个板块写什么" aria-label="Permalink to &quot;这个板块写什么&quot;">​</a></h2><ul><li><a href="./requirement.html">把需求写给 AI：一份秒杀需求的返工记录</a> —— 四个缺陷全是需求漏项，不是代码写错</li><li><a href="./acceptance.html">6 轮压测和 2 个 P0：AI 写的代码怎么验收</a> —— 压测、故障演练，以及我自己犯的三个验证错误</li></ul><h2 id="三条原则" tabindex="-1">三条原则 <a class="header-anchor" href="#三条原则" aria-label="Permalink to &quot;三条原则&quot;">​</a></h2><ol><li><strong>需求文档是验收标准的载体</strong> —— 写不出失败语义矩阵，说明需求还没想清楚，AI 只会填一个通用默认。</li><li><strong>&quot;已自测通过&quot;不构成证据</strong> —— 唯一能证明并发正确性的是对账数字，不是代码审查，也不是它自己的说明。</li><li><strong>怀疑自己的验证方法，先于怀疑代码</strong> —— 我三次误判全是&quot;没验证就以为验证了&quot;，AI 不会替你怀疑这一步。</li></ol><p>成本没有消失，只是从&quot;实现&quot;移到了&quot;把话说清楚&quot;和&quot;证明它对&quot;这两件事上。</p>',7)])])}const _=a(r,[["render",l]]);export{q as __pageData,_ as default};
